import XCTest

@testable import CodeConnect
@testable import CodeConnectKit

/// **The pairing link a QR carries**, against the daemon's own bytes.
///
/// `qr-link.txt` is what ccd emits (`fixtures/wire/`, regenerated by the
/// protocol crate's tests and copied here byte for byte): one line, then a
/// newline. A scanned link and an opened link are read by the same call, and an
/// older daemon's JSON still is.
final class PairingLinkTests: XCTestCase {

    private func emitted() throws -> String {
        let url = try XCTUnwrap(Bundle(for: type(of: self)).url(forResource: "qr-link", withExtension: "txt"))
        return try String(contentsOf: url, encoding: .utf8).trimmingCharacters(in: .newlines)
    }

    func testTheLinkTheDaemonEmitsDecodes() throws {
        let payload = try PairingQRPayload.decode(emitted()).get()
        XCTAssertEqual(payload, PairingQRPayload(host: "studio.tail0000.ts.net", port: 8787, code: "ABCD2345"))
        XCTAssertTrue(payload.endpoint.isPairingCode)
    }

    /// The link the app writes is the daemon's, byte for byte: a Mac shows the QR the computer would print.
    func testTheAppWritesTheLinkTheDaemonEmits() throws {
        XCTAssertEqual(try PairingQRPayload.decode(emitted()).get().link, try emitted())
    }

    /// An opened link reaches the app as a URL; its text is the same link.
    func testAnOpenedLinkDecodesAsTheScannedOneDoes() throws {
        let url = try XCTUnwrap(URL(string: try emitted()))
        XCTAssertEqual(
            try PairingQRPayload.decode(url.absoluteString).get(), try PairingQRPayload.decode(emitted()).get())
    }

    /// The JSON's checks, with the JSON's answers.
    func testALinkIsRefusedForWhatTheJSONIsRefusedFor() {
        func failure(_ fragment: String) -> PairingQRPayload.Failure? {
            guard case .failure(let failure) = PairingQRPayload.decode("https://codeconnect.sh/p#" + fragment)
            else { return nil }
            return failure
        }
        XCTAssertEqual(failure("v=2&h=studio.tail0000.ts.net&p=8787&c=ABCD2345"), .unsupportedVersion(2))
        XCTAssertEqual(failure("h=studio.tail0000.ts.net&p=8787&c=ABCD2345"), .unsupportedVersion(0))
        XCTAssertEqual(failure("v=1&p=8787&c=ABCD2345"), .missingField("host"))
        XCTAssertEqual(failure("v=1&h=studio.tail0000.ts.net&p=8787"), .missingField("code"))
        XCTAssertEqual(failure("v=1&h=studio.tail0000.ts.net&p=70000&c=ABCD2345"), .badPort(70000))
        guard case .unreachableHost("127.0.0.1", _)? = failure("v=1&h=127.0.0.1&p=8787&c=ABCD2345") else {
            return XCTFail("a loopback host is refused")
        }
    }

    /// A code is eight characters of an alphabet with digits in it; one that
    /// is all digits is still a code, not a number.
    func testACodeOfDigitsIsStillACode() throws {
        let payload = try PairingQRPayload.decode("https://codeconnect.sh/p#v=1&h=studio.tail0000.ts.net&c=23456789")
            .get()
        XCTAssertEqual(payload, PairingQRPayload(host: "studio.tail0000.ts.net", port: 8787, code: "23456789"))
    }

    func testOnlyCodeConnectsPairingPageIsALink() {
        for other in [
            "https://example.com/p#v=1&h=studio.tail0000.ts.net&c=ABCD2345",
            "https://codeconnect.sh/support#v=1&h=studio.tail0000.ts.net&c=ABCD2345",
            "http://codeconnect.sh/p#v=1&h=studio.tail0000.ts.net&c=ABCD2345",
            "https://codeconnect.sh/p",
        ] {
            XCTAssertEqual(PairingQRPayload.decode(other).failureValue, .notJSON, other)
        }
    }
}

extension Result {
    fileprivate var failureValue: Failure? {
        guard case .failure(let failure) = self else { return nil }
        return failure
    }
}
